{
  "policy_type": "rules",
  "name": "policy_ep_1",
  "rules": [
    {
      "if": [
        {"feature": "y", "op": ">", "value": 0.5},
        {"feature": "vy", "op": "<", "value": -0.5}
      ],
      "then": 2
    },
    {
      "if": [
        {"feature": "x", "op": ">", "value": 0.1},
        {"feature": "vx", "op": ">", "value": 0.1}
      ],
      "then": 1
    },
    {
      "if": [
        {"feature": "x", "op": "<", "value": -0.1},
        {"feature": "vx", "op": "<", "value": -0.1}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "theta", "op": ">", "value": 0.1}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "theta", "op": "<", "value": -0.1}
      ],
      "then": 1
    }
  ],
  "default_action": 0,
  "notes": "This initial policy is designed based on general principles for stable landings. The rules encourage reducing vertical speed when high above the ground, adjusting horizontal position when off-center, and correcting angular tilt. This should help the DQN agent learn to stabilize and land effectively without any prior policies influencing it."
}

